<template><div class="space-y-3 p-4"><div class="flex items-center justify-between"><h1 class="text-xl font-bold text-slate-800">Requests</h1><NuxtLink to="/buyer/post-request" class="text-xs font-semibold text-indigo-600">New request</NuxtLink></div><NuxtLink v-for="item in items" :key="item.id" :to="`/buyer/requests/${item.id}`" class="m-card block"><div class="flex justify-between gap-3"><p class="text-sm font-semibold text-slate-800">{{ item.title }}</p><span class="status-pill bg-indigo-50 text-indigo-600">{{ item.status }}</span></div><p class="mt-2 line-clamp-2 text-xs text-slate-400">{{ item.description }}</p></NuxtLink><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({ middleware: ['auth'] }); const { listProcurementRequests } = useCommerce(); const items = ref<any[]>([]); const error = ref(''); onMounted(async () => { try { items.value = (await listProcurementRequests()).items.filter((item: any) => item.portal_key === 'cebu') } catch (e: any) { error.value = e?.data?.detail || e?.message } })</script>
